import { useState } from "react";
import { Button, Chevron, Picture } from "../ui/primitives.jsx";
import { StageSection } from "./parts.jsx";
import { interactionTracking } from "../../lib/tracking.js";
import { Box, Paragraph } from "../ui/ds.jsx";

export default function PictureOfDayStage({ stage }) {
    const [open, setOpen] = useState(false);
    return (
        <StageSection stage={stage} label="Bild des Tages">
            <h2 className="mb-3 text-head-m font-bold uppercase">Bild des Tages</h2>
            <figure className="relative overflow-hidden rounded-teaser">
                <Picture picture={stage.picture} sizes="(min-width: 1024px) 980px, 100vw" />
                <figcaption className="absolute inset-x-0 bottom-0 bg-linear-to-t from-ink-900/85 to-transparent p-5 pt-16 text-white">
                    <Paragraph className="font-serif text-head-l">{stage.headline}</Paragraph>
                    <Paragraph className="mt-1 text-xs text-white/75">{stage.picture.source}</Paragraph>
                </figcaption>
            </figure>
            <Box className="mt-3">
                <Button variant="outline" aria-expanded={open} onClick={() => setOpen(!open)} {...interactionTracking("picture-story")}>
                    Geschichte zum Bild
                    <Chevron open={open} />
                </Button>
                {open ? <Paragraph className="mt-3 max-w-prose animate-fade-in text-base leading-relaxed text-ink-700 hyphens-auto">{stage.story}</Paragraph> : null}
            </Box>
        </StageSection>
    );
}
